/**
 * Browser-side session auth.
 *
 * The backend injects a random session token into index.html as
 * `window.__MAGUI_TOKEN__`. We read it here and attach it to every
 * outgoing API request and WebSocket handshake. When the token is
 * absent (Vite dev server serving its own HTML) the backend accepts
 * requests based on the dev-origin bypass instead.
 */

declare global {
  interface Window {
    __MAGUI_TOKEN__?: string
  }
}

/** Keep in sync with `WS_PROTOCOL_TAG` in `backend/web/auth.py`. */
export const WS_PROTOCOL_TAG = 'magui.auth.bearer'

export function getSessionToken(): string {
  return window.__MAGUI_TOKEN__ ?? ''
}

/** Bearer header for fetch. Empty when there is no injected token (dev). */
export function getAuthHeaders(): Record<string, string> {
  const token = [REDACTED]
  return token ? { Authorization: `Bearer ${token}` } : {}
}

/**
 * Open a WebSocket with the token carried in `Sec-WebSocket-Protocol`
 * (the only client-controlled handshake header in the browser). When
 * no token is present we open an unauth'd socket and rely on the
 * backend's dev-origin bypass.
 */
export function createAuthenticatedWebSocket(url: string): WebSocket {
  const token = [REDACTED]
  return token ? new WebSocket(url, [WS_PROTOCOL_TAG, token]) : new WebSocket(url)
}

/**
 * ExpandableActionText
 *
 * The "thoughts + actionResult" text block shown inside browser views.
 * Treats the two lines as a single interactive unit:
 * - thoughts: 2 lines max when collapsed (line-clamp-2)
 * - actionResult: 1 line max when collapsed (truncate)
 * - If either line is truncated, the whole block becomes clickable and shows a
 *   "Click to expand" hover hint
 * - Click anywhere → both expand together; click again → both collapse
 *
 * Truncation is detected via ResizeObserver, so the affordance auto-updates
 * as the surrounding container resizes.
 *
 * Used by both `ActionDescription` (expanded view) and `DescriptionOverlay`
 * (embedded overlay).
 */

import { useEffect, useRef, useState } from 'react'
import { Tooltip, TooltipContent, TooltipTrigger } from '@/components/ui/tooltip'
import { cn } from '@/lib/utils'

// =============================================================================
// Helpers
// =============================================================================

/**
 * Detects whether a block-level element's content is visually truncated by CSS
 * (line-clamp or text-overflow). Re-checks on element resize and whenever
 * `text` changes (e.g. when switching to a different screenshot).
 *
 * Pass `enabled: false` to pause the ResizeObserver (e.g. while expanded). The
 * last measured value is preserved so the caller stays interactive on the same
 * render that toggles back to collapsed.
 */
function useIsTruncated(
  ref: React.RefObject<HTMLElement | null>,
  enabled: boolean,
  text: string | undefined
) {
  const [truncated, setTruncated] = useState(false)

  useEffect(() => {
    if (!enabled) return
    const el = ref.current
    if (!el) return

    const check = () => {
      const overflow = el.scrollHeight > el.clientHeight || el.scrollWidth > el.clientWidth
      setTruncated(overflow)
    }

    const observer = new ResizeObserver(check)
    observer.observe(el)
    // `check()` runs synchronously here so a `text` change immediately
    // overwrites any stale value from the previous render.
    check()

    return () => observer.disconnect()
  }, [ref, enabled, text])

  // When text becomes empty there is nothing to truncate. Returning `false &&`
  // here keeps the caller's `isInteractive` accurate without triggering an
  // extra effect-driven setState.
  return text ? truncated : false
}

// =============================================================================
// Component
// =============================================================================

interface ExpandableActionTextProps {
  thoughts?: string
  actionResult?: string
  /** Extra class names applied to each line (e.g. text color). */
  textClassName?: string
}

export function ExpandableActionText({
  thoughts,
  actionResult,
  textClassName,
}: ExpandableActionTextProps) {
  const thoughtsRef = useRef<HTMLParagraphElement>(null)
  const actionRef = useRef<HTMLParagraphElement>(null)
  const [isExpanded, setIsExpanded] = useState(false)
  // Only detect truncation while collapsed; once expanded, the block stays
  // clickable so the user can collapse it again.
  const isThoughtsTruncated = useIsTruncated(thoughtsRef, !isExpanded, thoughts)
  const isActionTruncated = useIsTruncated(actionRef, !isExpanded, actionResult)
  const isInteractive = isThoughtsTruncated || isActionTruncated || isExpanded

  if (!thoughts && !actionResult) return null

  const toggle = () => setIsExpanded((v) => !v)

  // Single Tooltip wraps the whole block so any hover/click on either line
  // shows the same hint and toggles the same state. JSX tree stays stable
  // (Tooltip + TooltipTrigger + inner div + <p> refs all constant) so the
  // ResizeObserver-based detection keeps working across re-renders.
  return (
    <Tooltip>
      <TooltipTrigger asChild>
        <div
          role={isInteractive ? 'button' : undefined}
          tabIndex={isInteractive ? 0 : undefined}
          aria-expanded={isInteractive ? isExpanded : undefined}
          onClick={isInteractive ? toggle : undefined}
          onKeyDown={
            isInteractive
              ? (e) => {
                  if (e.key === 'Enter' || e.key === ' ') {
                    e.preventDefault()
                    toggle()
                  }
                }
              : undefined
          }
          className={cn(
            isInteractive &&
              'focus-visible:ring-ring cursor-pointer rounded-sm focus-visible:ring-2 focus-visible:outline-none'
          )}
        >
          {thoughts && (
            <p
              ref={thoughtsRef}
              className={cn('text-sm leading-5', !isExpanded && 'line-clamp-2', textClassName)}
            >
              {thoughts}
            </p>
          )}
          {actionResult && (
            <p
              ref={actionRef}
              className={cn(
                'text-sm leading-5 font-bold',
                !isExpanded && 'truncate',
                textClassName
              )}
            >
              {actionResult}
            </p>
          )}
        </div>
      </TooltipTrigger>
      {isInteractive && (
        <TooltipContent>{isExpanded ? 'Click to collapse' : 'Click to expand'}</TooltipContent>
      )}
    </Tooltip>
  )
}

/**
 * Action Description Component
 *
 * Displays CUA action thoughts and result inside the expanded browser view.
 *
 * Layout responsibilities live here:
 * - Container has a minimum height (no shrink jitter); grows when content expands
 * - Bottom-anchored so the text stays right above the toolbar; expanded content
 *   grows upward.
 *
 * Per-block interaction (click-to-expand, tooltip hint, etc.) lives in
 * `ExpandableActionText`, which is shared with `DescriptionOverlay`.
 */

import { ExpandableActionText } from './ExpandableActionText'

// =============================================================================
// Types
// =============================================================================

interface ActionDescriptionProps {
  thoughts?: string
  actionResult?: string
}

// =============================================================================
// Component
// =============================================================================

export function ActionDescription({ thoughts, actionResult }: ActionDescriptionProps) {
  return (
    <div className="flex min-h-[68px] flex-col justify-end">
      <ExpandableActionText
        thoughts={thoughts}
        actionResult={actionResult}
        textClassName="text-foreground"
      />
    </div>
  )
}

"""Session-token authentication for the backend API and WebSocket.

Random per-process token, injected into the served ``index.html`` for
the prod frontend and bypassed when requests come from Vite's dev
origin. See README for the full threat model.
"""

from __future__ import annotations

import hmac
import secrets

from fastapi import Request
from fastapi.responses import JSONResponse

# ---------------------------------------------------------------------------
# Token
# ---------------------------------------------------------------------------

# 256 bits of entropy, URL-safe base64. Process-lifetime only.
SESSION_TOKEN: str = secrets.token_urlsafe(32)

# Sec-WebSocket-Protocol tag used for the WS handshake. Client offers
# [WS_PROTOCOL_TAG, <token>], server echoes WS_PROTOCOL_TAG on accept.
WS_PROTOCOL_TAG = "magui.auth.bearer"


# ---------------------------------------------------------------------------
# Validation
# ---------------------------------------------------------------------------


def is_valid_token(token: str) -> bool:
    return hmac.compare_digest(token.encode(), SESSION_TOKEN.encode())


def is_valid_bearer_header(header_value: str) -> bool:
    if not header_value.startswith("Bearer "):
        return False
    return is_valid_token(header_value[len("Bearer ") :])


# ---------------------------------------------------------------------------
# Public-path allowlist
# ---------------------------------------------------------------------------

PUBLIC_API_PATHS: frozenset[str] = frozenset(
    {
        "/api/health",
        "/api/version",
    }
)


def is_public_path(path: str) -> bool:
    return path in PUBLIC_API_PATHS


# ---------------------------------------------------------------------------
# Dev-mode origin bypass
# ---------------------------------------------------------------------------

# Defends against browser-based attackers only: Origin and Referer are
# forbidden request headers, so in-browser JavaScript cannot forge
# them. Non-browser clients (curl, shell scripts, malicious local
# processes) can set any header they want and bypass this check —
# that's out of scope, matching the token-in-HTML model (a local
# process can also scrape the token from the HTML shell).
DEV_ORIGINS: frozenset[str] = frozenset(
    {
        "http://localhost:5173",
        "http://127.0.0.1:5173",
    }
)


def is_dev_origin_request(request: Request) -> bool:
    if request.headers.get("origin", "") in DEV_ORIGINS:
        return True
    referer = request.headers.get("referer", "")
    return any(referer == dev or referer.startswith(dev + "/") for dev in DEV_ORIGINS)


# ---------------------------------------------------------------------------
# HTML injection
# ---------------------------------------------------------------------------


def inject_token_into_html(html: str) -> str:
    # SESSION_TOKEN is URL-safe base64 (A-Za-z0-9_-), so no JS string
    # escaping is needed when wrapped in double quotes.
    script = f'<script>window.__MAGUI_TOKEN__="{SESSION_TOKEN}";</script>'
    if "</head>" in html:
        return html.replace("</head>", f"{script}</head>", 1)
    return script + html


# ---------------------------------------------------------------------------
# Host header allowlist (DNS-rebinding defense)
# ---------------------------------------------------------------------------

_ALLOWED_HOSTS: frozenset[str] = frozenset({"localhost", "127.0.0.1"})


def is_allowed_host(host_header: str) -> bool:
    if not host_header:
        return True
    host = host_header.rsplit(":", 1)[0]
    return host in _ALLOWED_HOSTS


# ---------------------------------------------------------------------------
# Middleware helpers (wired up in app.py)
# ---------------------------------------------------------------------------


def unauthorized_response() -> JSONResponse:
    return JSONResponse(
        status_code=401,
        content={"status": False, "message": "Unauthorized"},
    )


def bad_host_response() -> JSONResponse:
    return JSONResponse(
        status_code=400,
        content={"status": False, "message": "Bad Host header"},
    )


async def require_api_auth(request: Request) -> JSONResponse | None:
    """Return a 401 response if auth is required and missing; ``None`` otherwise."""
    path = request.url.path
    if not path.startswith("/api/"):
        return None
    if is_public_path(path):
        return None
    if is_dev_origin_request(request):
        return None
    if not is_valid_bearer_header(request.headers.get("authorization", "")):
        return unauthorized_response()
    return None

"""Unit tests for the session-auth helpers in backend/web/auth.py."""

from unittest.mock import MagicMock

import pytest
from fastapi import Request

from magentic_ui.backend.web import auth


class TestTokenValidation:
    def test_valid_token_accepts_current_session_token(self):
        assert auth.is_valid_token(auth.SESSION_TOKEN)

    def test_valid_token_rejects_wrong(self):
        assert not auth.is_valid_token("wrong-token")

    def test_valid_token_rejects_empty(self):
        assert not auth.is_valid_token("")

    def test_bearer_header_valid(self):
        assert auth.is_valid_bearer_header(f"Bearer {auth.SESSION_TOKEN}")

    def test_bearer_header_wrong_scheme(self):
        assert not auth.is_valid_bearer_header(f"Token {auth.SESSION_TOKEN}")

    def test_bearer_header_missing_token(self):
        assert not auth.is_valid_bearer_header("Bearer ")

    def test_bearer_header_empty(self):
        assert not auth.is_valid_bearer_header("")


class TestPublicPath:
    @pytest.mark.parametrize("path", ["/api/health", "/api/version"])
    def test_public(self, path: str):
        assert auth.is_public_path(path)

    @pytest.mark.parametrize(
        "path",
        [
            "/api/sessions",
            "/api/runs",
            "/api/onboarding/status",
            "/api/filesystem/list",
            "/",
            "/api/",
        ],
    )
    def test_not_public(self, path: str):
        assert not auth.is_public_path(path)


class TestDevOriginRequest:
    def _request(self, origin: str = "", referer: str = "") -> Request:
        req = MagicMock(spec=Request)
        headers = {}
        if origin:
            headers["origin"] = origin
        if referer:
            headers["referer"] = referer
        req.headers = headers
        return req

    @pytest.mark.parametrize(
        "origin",
        ["http://localhost:5173", "http://127.0.0.1:5173"],
    )
    def test_dev_origins_accepted(self, origin: str):
        assert auth.is_dev_origin_request(self._request(origin=origin))

    @pytest.mark.parametrize(
        "origin",
        [
            "",
            "http://localhost:8081",
            "http://127.0.0.1:8081",
            "http://evil.com",
            "http://localhost:3000",
            "https://localhost:5173",  # different scheme
        ],
    )
    def test_non_dev_origins_rejected(self, origin: str):
        assert not auth.is_dev_origin_request(self._request(origin=origin))

    @pytest.mark.parametrize(
        "referer",
        [
            "http://localhost:5173",
            "http://localhost:5173/",
            "http://localhost:5173/sessions/abc",
            "http://127.0.0.1:5173/anything",
        ],
    )
    def test_dev_referer_accepted_when_origin_missing(self, referer: str):
        assert auth.is_dev_origin_request(self._request(referer=referer))

    @pytest.mark.parametrize(
        "referer",
        [
            "",
            "http://evil.com/",
            "http://localhost:5173.evil.com/",  # prefix-match attack
            "http://localhost:5173evil.com/",
            "http://localhost:3000/",
        ],
    )
    def test_non_dev_referer_rejected(self, referer: str):
        assert not auth.is_dev_origin_request(self._request(referer=referer))

    def test_origin_wins_when_both_present(self):
        # An evil Referer cannot override a trusted Origin check; just
        # verify the function still returns True when at least one source
        # vouches for the request.
        assert auth.is_dev_origin_request(
            self._request(
                origin="http://localhost:5173",
                referer="http://evil.com/",
            )
        )


class TestInjectTokenIntoHtml:
    def test_injected_before_close_head(self):
        html = "<html><head><title>x</title></head><body></body></html>"
        out = auth.inject_token_into_html(html)
        assert "window.__MAGUI_TOKEN__" in out
        assert auth.SESSION_TOKEN in out
        # Script must appear before </head>
        assert out.index("window.__MAGUI_TOKEN__") < out.index("</head>")

    def test_prepended_when_no_head(self):
        html = "<html><body></body></html>"
        out = auth.inject_token_into_html(html)
        assert out.startswith("<script>")
        assert "window.__MAGUI_TOKEN__" in out

    def test_only_replaces_first_close_head(self):
        html = "<html><head></head><body><!-- </head> --></body></html>"
        out = auth.inject_token_into_html(html)
        # Script injected once, at the real </head>
        assert out.count("<script>window.__MAGUI_TOKEN__") == 1


class TestAllowedHost:
    @pytest.mark.parametrize(
        "host",
        [
            "",  # Missing header allowed
            "localhost",
            "localhost:8081",
            "127.0.0.1",
            "127.0.0.1:5173",
        ],
    )
    def test_allowed(self, host: str):
        assert auth.is_allowed_host(host)

    @pytest.mark.parametrize(
        "host",
        [
            "evil.com",
            "evil.com:8081",
            "attacker.example",
            "192.168.1.10:8081",
        ],
    )
    def test_rejected(self, host: str):
        assert not auth.is_allowed_host(host)

# pyright: reportUnusedFunction=false
#
# FastAPI route handlers inside _build_app() are registered via `@app.get(...)`
# / `@app.middleware(...)` decorators; pyright can't follow that indirection
# and would flag each handler as unused. We don't need any other suppressions.

"""Integration tests for the session-auth middleware and WS handshake.

These build a minimal FastAPI app that wires the same middleware + a
WebSocket endpoint that reuses the real authentication helper. Keeping
the test app small avoids pulling the full magentic-ui server
(database init, sandbox managers, etc.) into the fixture.
"""

from __future__ import annotations

from pathlib import Path
from typing import Awaitable, Callable, Generator

import pytest
from fastapi import FastAPI, Request, WebSocket
from fastapi.middleware.cors import CORSMiddleware
from fastapi.responses import Response
from fastapi.testclient import TestClient

from magentic_ui.backend.web.app import SPAStaticFiles
from magentic_ui.backend.web.auth import (
    SESSION_TOKEN,
    WS_PROTOCOL_TAG,
    bad_host_response,
    is_allowed_host,
    require_api_auth,
)
from magentic_ui.backend.web.routes.ws import authenticate_websocket


def _build_app() -> FastAPI:
    app = FastAPI()

    @app.middleware("http")
    async def api_auth_middleware(
        request: Request,
        call_next: Callable[[Request], Awaitable[Response]],
    ) -> Response:
        unauthorized = await require_api_auth(request)
        if unauthorized is not None:
            return unauthorized
        return await call_next(request)

    app.add_middleware(
        CORSMiddleware,
        allow_origins=[
            "http://localhost:8081",
            "http://127.0.0.1:8081",
            "http://localhost:5173",
            "http://127.0.0.1:5173",
        ],
        allow_credentials=True,
        allow_methods=["*"],
        allow_headers=["*"],
    )

    @app.middleware("http")
    async def host_header_middleware(
        request: Request,
        call_next: Callable[[Request], Awaitable[Response]],
    ) -> Response:
        if not is_allowed_host(request.headers.get("host", "")):
            return bad_host_response()
        return await call_next(request)

    @app.get("/api/health")
    async def health() -> dict[str, bool]:
        return {"ok": True}

    @app.get("/api/version")
    async def version() -> dict[str, str]:
        return {"version": "test"}

    @app.get("/api/sessions")
    async def sessions() -> dict[str, object]:
        return {"ok": True, "data": []}

    @app.websocket("/api/ws/runs/{run_id}")
    async def ws_endpoint(websocket: WebSocket, run_id: int) -> None:
        allowed, subprotocol = authenticate_websocket(websocket)
        if not allowed:
            await websocket.close(code=4401, reason="Unauthorized")
            return
        await websocket.accept(subprotocol=subprotocol)
        await websocket.send_json({"run_id": run_id, "ok": True})
        await websocket.close()

    return app


@pytest.fixture
def client() -> Generator[TestClient, None, None]:
    # Override default Host (`testserver`) so the Host-header middleware
    # accepts TestClient requests out of the box. Using `with` ensures
    # lifespan + WS cleanup between tests — without it, a successful WS
    # connect can leave event-loop state that pollutes the next test.
    with TestClient(_build_app(), base_url="http://localhost") as c:
        yield c


# ---------------------------------------------------------------------------
# HTTP auth middleware
# ---------------------------------------------------------------------------


class TestApiAuthMiddleware:
    def test_health_public(self, client: TestClient):
        assert client.get("/api/health").status_code == 200

    def test_version_public(self, client: TestClient):
        assert client.get("/api/version").status_code == 200

    def test_protected_route_requires_token(self, client: TestClient):
        r = client.get("/api/sessions")
        assert r.status_code == 401
        assert r.json()["status"] is False

    def test_protected_route_accepts_valid_token(self, client: TestClient):
        r = client.get(
            "/api/sessions",
            headers={"Authorization": f"Bearer {SESSION_TOKEN}"},
        )
        assert r.status_code == 200

    def test_protected_route_rejects_wrong_token(self, client: TestClient):
        r = client.get(
            "/api/sessions",
            headers={"Authorization": "Bearer not-the-real-token"},
        )
        assert r.status_code == 401

    def test_protected_route_rejects_wrong_scheme(self, client: TestClient):
        r = client.get(
            "/api/sessions",
            headers={"Authorization": f"Token {SESSION_TOKEN}"},
        )
        assert r.status_code == 401

    def test_dev_origin_bypass(self, client: TestClient):
        r = client.get(
            "/api/sessions",
            headers={"Origin": "http://localhost:5173"},
        )
        assert r.status_code == 200

    def test_dev_origin_loopback_variant(self, client: TestClient):
        r = client.get(
            "/api/sessions",
            headers={"Origin": "http://127.0.0.1:5173"},
        )
        assert r.status_code == 200

    def test_other_origin_still_requires_token(self, client: TestClient):
        r = client.get(
            "/api/sessions",
            headers={"Origin": "http://evil.com"},
        )
        assert r.status_code == 401

    def test_dev_referer_bypass_when_origin_missing(self, client: TestClient):
        # Simulates a browser same-origin GET from Vite: no Origin, but
        # Referer is populated from the page URL.
        r = client.get(
            "/api/sessions",
            headers={"Referer": "http://localhost:5173/sessions"},
        )
        assert r.status_code == 200

    def test_non_dev_referer_still_requires_token(self, client: TestClient):
        r = client.get(
            "/api/sessions",
            headers={"Referer": "http://evil.com/"},
        )
        assert r.status_code == 401


# ---------------------------------------------------------------------------
# Host header middleware (DNS-rebinding defense)
# ---------------------------------------------------------------------------


class TestHostHeaderMiddleware:
    def test_allowed_localhost(self, client: TestClient):
        r = client.get("/api/health", headers={"Host": "localhost:8081"})
        assert r.status_code == 200

    def test_allowed_loopback(self, client: TestClient):
        r = client.get("/api/health", headers={"Host": "127.0.0.1:8081"})
        assert r.status_code == 200

    def test_rejects_foreign_host(self, client: TestClient):
        r = client.get("/api/health", headers={"Host": "evil.com"})
        assert r.status_code == 400
        assert r.json()["status"] is False


# ---------------------------------------------------------------------------
# CORS
# ---------------------------------------------------------------------------


class TestCors:
    def test_preflight_from_allowed_origin(self, client: TestClient):
        r = client.options(
            "/api/sessions",
            headers={
                "Origin": "http://localhost:5173",
                "Access-Control-Request-Method": "GET",
            },
        )
        assert r.status_code == 200
        assert r.headers.get("access-control-allow-origin") == "http://localhost:5173"

    def test_preflight_from_disallowed_origin(self, client: TestClient):
        r = client.options(
            "/api/sessions",
            headers={
                "Origin": "http://evil.com",
                "Access-Control-Request-Method": "GET",
            },
        )
        assert r.status_code == 400
        assert "access-control-allow-origin" not in r.headers


# ---------------------------------------------------------------------------
# WebSocket auth
# ---------------------------------------------------------------------------


class TestSPAStaticFilesInjection:
    """Regression test: the mounted SPA handler must inject the token into
    the HTML shell for every entry point (`/`, `/index.html`, and SPA
    fallback paths). Starlette hands the path ``"."`` for `GET /`, which
    is easy to miss in a naive equality check.
    """

    @pytest.fixture
    def spa_client(self, tmp_path: Path) -> TestClient:
        (tmp_path / "index.html").write_text(
            "<html><head></head><body></body></html>", encoding="utf-8"
        )
        app = FastAPI()
        app.mount("/", SPAStaticFiles(directory=tmp_path, html=True))
        return TestClient(app, base_url="http://localhost")

    @pytest.mark.parametrize(
        "path",
        ["/", "/index.html", "/settings", "/sessions/abc/xyz"],
    )
    def test_token_is_injected(self, spa_client: TestClient, path: str):
        r = spa_client.get(path)
        assert r.status_code == 200
        assert 'window.__MAGUI_TOKEN__="' in r.text
        # Guard against caching the token in a CDN or browser.
        assert "no-store" in (r.headers.get("cache-control") or "")


class TestWebSocketAuth:
    """Tests for `authenticate_websocket()`: subprotocol bearer, dev-origin
    bypass, and Host-header check."""

    @staticmethod
    def _ws(
        *,
        host: str = "localhost",
        origin: str = "",
        subprotocols: list[str] | None = None,
    ):
        from unittest.mock import MagicMock
        from fastapi import WebSocket

        ws = MagicMock(spec=WebSocket)
        ws.headers = {"host": host}
        if origin:
            ws.headers["origin"] = origin
        ws.scope = {"subprotocols": subprotocols or []}
        return ws

    def test_accepts_valid_subprotocol_token(self):
        ws = self._ws(subprotocols=[WS_PROTOCOL_TAG, SESSION_TOKEN])
        assert authenticate_websocket(ws) == (True, WS_PROTOCOL_TAG)

    def test_rejects_wrong_token(self):
        ws = self._ws(subprotocols=[WS_PROTOCOL_TAG, "wrong-token"])
        assert authenticate_websocket(ws) == (False, None)

    def test_rejects_no_subprotocol_from_non_dev_origin(self):
        ws = self._ws()
        assert authenticate_websocket(ws) == (False, None)

    def test_rejects_wrong_subprotocol_tag(self):
        ws = self._ws(subprotocols=["wrong.tag", SESSION_TOKEN])
        assert authenticate_websocket(ws) == (False, None)

    def test_accepts_dev_origin_without_token(self):
        ws = self._ws(origin="http://localhost:5173")
        assert authenticate_websocket(ws) == (True, None)

    def test_rejects_disallowed_host(self):
        ws = self._ws(
            host="evil.com",
            subprotocols=[WS_PROTOCOL_TAG, SESSION_TOKEN],
        )
        assert authenticate_websocket(ws) == (False, None)

    def test_smoke_end_to_end_handshake(self):
        """End-to-end handshake through a real TestClient."""
        with TestClient(_build_app(), base_url="http://localhost") as c:
            with c.websocket_connect(
                "/api/ws/runs/42",
                subprotocols=[WS_PROTOCOL_TAG, SESSION_TOKEN],
                headers={"Host": "localhost"},
            ) as ws:
                assert ws.receive_json() == {"run_id": 42, "ok": True}

